10→
11→namespace DemoApp.CollaborativeTaskBoard;
12→
13→sealed class Program
14→{
15→  [STAThread]
16→  public static void Main(string[] args)
17→  {
18→    IHost host = CreateHostBuilder(args).Build();
19→    App.Services = host.Services;
20→
21→    _ = host.StartAsync();
22→
23→    BuildAvaloniaApp()
24→      .StartWithClassicDesktopLifetime(args);
25→  }
26→
27→  public static IHostBuilder CreateHostBuilder(string[] args) =>
28→    Host.CreateDefaultBuilder(args)
29→      .ConfigureLogging(logging =>
30→      {
31→        logging.ClearProviders();
32→        logging.AddDebug();
33→        logging.AddConsole();
34→        logging.SetMinimumLevel(LogLevel.Trace);
35→      })
36→      .AddServiceDefaults()
37→#if DEBUG
38→      .AddAvaloniaMcpConnector(options => options.AppName = "CollaborativeTaskBoard")
39→#endif
40→      .ConfigureServices((context, services) =>
41→      {
42→        string hubUrl = ResolveHubUrl();
43→        services.AddSingleton(new RepoServiceOptions
44→        {
45→          HubUrl = hubUrl,
46→          AppName = "CollaborativeTaskBoard"
47→        });
48→        services.AddSingleton<RepoService>();
49→      });
50→
51→  public static AppBuilder BuildAvaloniaApp()
52→    => AppBuilder.Configure<App>()
53→      .UsePlatformDetect()
54→      .WithInterFont()
55→      .LogToTrace()
56→      .UseReactiveUI();
57→
58→  static string ResolveHubUrl()
59→  {
60→    // Aspire service discovery env vars
61→    string? hubUrl = Environment.GetEnvironmentVariable("services__api__https__0")
62→      ?? Environment.GetEnvironmentVariable("services__api__http__0");
63→
64→    if(!string.IsNullOrEmpty(hubUrl))
65→    {
66→      return $"{hubUrl}/hubs/documents";
67→    }
68→
69→    // Fallback to HUB_URL env var or default
70→    return Environment.GetEnvironmentVariable("HUB_URL")
71→      ?? "https://localhost:5001/hubs/documents";
72→  }
73→}
