 10→namespace Microsoft.Extensions.Hosting;
 11→
 12→// Adds common Aspire services: service discovery, resilience, health checks, and OpenTelemetry.
 13→// This project should be referenced by each service project in your solution.
 14→// To learn more about using this project, see https://aka.ms/dotnet/aspire/service-defaults
 15→public static class Extensions
 16→{
 17→  private const string HealthEndpointPath = "/health";
 18→  private const string AlivenessEndpointPath = "/alive";
 19→
 20→  public static TBuilder AddServiceDefaults<TBuilder>(this TBuilder builder) where TBuilder : IHostApplicationBuilder
 21→  {
 22→    builder.ConfigureOpenTelemetry();
 23→
 24→    builder.AddDefaultHealthChecks();
 25→
 26→    builder.Services.AddServiceDiscovery();
 27→
 28→    builder.Services.ConfigureHttpClientDefaults(http =>
 29→    {
 30→      // Turn on resilience by default
 31→      http.AddStandardResilienceHandler();
 32→
 33→      // Turn on service discovery by default
 34→      http.AddServiceDiscovery();
 35→    });
 36→
 37→    // Uncomment the following to restrict the allowed schemes for service discovery.
 38→    // builder.Services.Configure<ServiceDiscoveryOptions>(options =>
 39→    // {
 40→    //     options.AllowedSchemes = ["https"];
 41→    // });
 42→
 43→    return builder;
 44→  }
 45→
 46→  public static IHostBuilder AddServiceDefaults(this IHostBuilder builder)
 47→  {
 48→    builder.ConfigureLogging((context, logging) =>
 49→    {
 50→      logging.AddOpenTelemetry(otel =>
 51→      {
 52→        otel.IncludeFormattedMessage = true;
 53→        otel.IncludeScopes = true;
 54→      });
 55→    });
 56→
 57→    builder.ConfigureServices((context, services) =>
 58→    {
 59→      services.AddHealthChecks()
 60→        .AddCheck("self", () => HealthCheckResult.Healthy(), ["live"]);
 61→
 62→      services.AddServiceDiscovery();
 63→
 64→      services.ConfigureHttpClientDefaults(http =>
 65→      {
 66→        http.AddStandardResilienceHandler();
 67→        http.AddServiceDiscovery();
 68→      });
 69→
 70→      services.AddOpenTelemetry()
 71→        .WithMetrics(metrics =>
 72→        {
 73→          metrics.AddHttpClientInstrumentation()
 74→            .AddRuntimeInstrumentation();
 75→        })
 76→        .WithTracing(tracing =>
 77→        {
 78→          tracing.AddSource(context.HostingEnvironment.ApplicationName)
 79→            .AddHttpClientInstrumentation();
 80→        });
 81→
 82→      var useOtlpExporter = !string.IsNullOrWhiteSpace(
 83→        context.Configuration["OTEL_EXPORTER_OTLP_ENDPOINT"]);
 84→      if(useOtlpExporter)
 85→      {
 86→        services.AddOpenTelemetry().UseOtlpExporter();
 87→      }
 88→    });
 89→
 90→    return builder;
 91→  }
 92→
 93→  public static TBuilder ConfigureOpenTelemetry<TBuilder>(this TBuilder builder)
 94→    where TBuilder : IHostApplicationBuilder
 95→  {
 96→    builder.Logging.AddOpenTelemetry(logging =>
 97→    {
 98→      logging.IncludeFormattedMessage = true;
 99→      logging.IncludeScopes = true;
100→    });
101→
102→    builder.Services.AddOpenTelemetry()
103→      .WithMetrics(metrics =>
104→      {
105→        metrics.AddAspNetCoreInstrumentation()
106→          .AddHttpClientInstrumentation()
107→          .AddRuntimeInstrumentation()
108→          .AddMeter("Microsoft.Orleans");
109→      })
110→      .WithTracing(tracing =>
111→      {
112→        tracing.AddSource("Microsoft.Orleans.Runtime");
113→        tracing.AddSource("Microsoft.Orleans.Application");
114→        
115→        tracing.AddSource(builder.Environment.ApplicationName)
116→          .AddAspNetCoreInstrumentation(tracing =>
117→            // Exclude health check requests from tracing
118→            tracing.Filter = context =>
119→              !context.Request.Path.StartsWithSegments(HealthEndpointPath)
120→              && !context.Request.Path.StartsWithSegments(AlivenessEndpointPath)
121→          )
122→          // Uncomment the following line to enable gRPC instrumentation (requires the OpenTelemetry.Instrumentation.GrpcNetClient package)
123→          //.AddGrpcClientInstrumentation()
124→          .AddHttpClientInstrumentation();
125→      });
126→
127→    builder.AddOpenTelemetryExporters();
128→
129→    return builder;
130→  }
131→
132→  private static TBuilder AddOpenTelemetryExporters<TBuilder>(this TBuilder builder)
133→    where TBuilder : IHostApplicationBuilder
134→  {
135→    var useOtlpExporter = !string.IsNullOrWhiteSpace(builder.Configuration["OTEL_EXPORTER_OTLP_ENDPOINT"]);
136→
137→    if(useOtlpExporter)
138→    {
139→      builder.Services.AddOpenTelemetry().UseOtlpExporter();
140→    }
141→
142→    // Uncomment the following lines to enable the Azure Monitor exporter (requires the Azure.Monitor.OpenTelemetry.AspNetCore package)
143→    //if (!string.IsNullOrEmpty(builder.Configuration["APPLICATIONINSIGHTS_CONNECTION_STRING"]))
144→    //{
145→    //    builder.Services.AddOpenTelemetry()
146→    //       .UseAzureMonitor();
147→    //}
148→
149→    return builder;
150→  }
151→
152→  public static TBuilder AddDefaultHealthChecks<TBuilder>(this TBuilder builder)
153→    where TBuilder : IHostApplicationBuilder
154→  {
155→    builder.Services.AddHealthChecks()
156→      // Add a default liveness check to ensure app is responsive
157→      .AddCheck("self", () => HealthCheckResult.Healthy(), ["live"]);
158→
159→    return builder;
160→  }
161→
162→  public static WebApplication MapDefaultEndpoints(this WebApplication app)
163→  {
164→    // Adding health checks endpoints to applications in non-development environments has security implications.
165→    // See https://aka.ms/dotnet/aspire/healthchecks for details before enabling these endpoints in non-development environments.
166→    if(app.Environment.IsDevelopment())
167→    {
168→      // All health checks must pass for app to be considered ready to accept traffic after starting
169→      app.MapHealthChecks(HealthEndpointPath);
170→
171→      // Only health checks tagged with the "live" tag must pass for app to be considered alive
172→      app.MapHealthChecks(AlivenessEndpointPath, new HealthCheckOptions { Predicate = r => r.Tags.Contains("live") });
173→    }
174→
175→    return app;
176→  }
177→}

