  1→using Microsoft.Extensions.Caching.Memory;
  2→using Ray.Automerge.Repository.Storage;
  3→
  4→namespace Ray.Automerge.Repository.Storage.FileSystem;
  5→
  6→/// <summary>
  7→/// File system storage adapter that persists data to local disk with in-memory caching.
  8→/// </summary>
  9→/// <remarks>
 10→/// <para>
 11→/// This adapter stores data in a hierarchical directory structure with sharding to prevent
 12→/// directory overflow. The first key component is split: first 2 chars become a directory,
 13→/// remaining chars become a subdirectory.
 14→/// </para>
 15→/// <para>
 16→/// Example: Key ["abc123", "snapshot", "hash"] → baseDir/ab/c123/snapshot/hash
 17→/// </para>
 18→/// <para>
 19→/// Data is cached in memory using MemoryCache for fast repeated reads.
 20→/// </para>
 21→/// </remarks>
 22→[PublicAPI]
 23→public sealed class FileSystemStorageAdapter : StorageAdapterBase, IDisposable
 24→{
 25→  readonly string _baseDirectory;
 26→  readonly IMemoryCache _cache;
 27→  readonly SemaphoreSlim _lock = new(1, 1);
 28→  readonly TimeSpan _cacheSlidingExpiration;
 29→  bool _disposed;
 30→
 31→
 32→  /// <summary>
 33→  /// Creates a new file system storage adapter.
 34→  /// </summary>
 35→  /// <param name="baseDirectory">Base directory for storage. Created if it doesn't exist.</param>
 36→  /// <param name="options">Optional configuration. If null, uses default settings.</param>
 37→  public FileSystemStorageAdapter(string baseDirectory, FileSystemStorageOptions? options = null)
 38→  {
 39→    if(string.IsNullOrWhiteSpace(baseDirectory))
 40→      throw new ArgumentException("Base directory cannot be null or whitespace", nameof(baseDirectory));
 41→
 42→    options ??= new FileSystemStorageOptions();
 43→
 44→    _baseDirectory = Path.GetFullPath(baseDirectory);
 45→    _cacheSlidingExpiration = options.CacheSlidingExpiration;
 46→
 47→    // Initialize cache with size limit
 48→    _cache = new MemoryCache(new MemoryCacheOptions
 49→    {
 50→      SizeLimit = options.CacheSizeLimit
 51→    });
 52→
 53→    // Create base directory if it doesn't exist
 54→    Directory.CreateDirectory(_baseDirectory);
 55→  }
 56→
 57→
 58→  /// <summary>
 59→  /// Loads data for a storage key. Checks cache first, then disk.
 60→  /// </summary>
 61→  public override async Task<byte[]?> Load(StorageKey key)
 62→  {
 63→    ThrowIfDisposed();
 64→
 65→    var cacheKey = GetCacheKey(key);
 66→
 67→    // Try cache first
 68→    if(_cache.TryGetValue(cacheKey, out byte[]? cachedData))
 69→    {
 70→      return cachedData;
 71→    }
 72→
 73→    // Load from disk
 74→    var filePath = GetFilePath(key);
 75→
 76→    await _lock.WaitAsync();
 77→    try
 78→    {
 79→      if(!File.Exists(filePath))
 80→        return null;
 81→
 82→      var data = await File.ReadAllBytesAsync(filePath);
 83→
 84→      // Store in cache with sliding expiration
 85→      var cacheOptions = new MemoryCacheEntryOptions()
 86→        .SetSize(data.Length)
 87→        .SetSlidingExpiration(_cacheSlidingExpiration);
 88→
 89→      _cache.Set(cacheKey, data, cacheOptions);
 90→
 91→      return data;
 92→    }
 93→    catch(FileNotFoundException)
 94→    {
 95→      return null;
 96→    }
 97→    catch(DirectoryNotFoundException)
 98→    {
 99→      return null;
100→    }
101→    finally
102→    {
103→      _lock.Release();
104→    }
105→  }
106→
107→  /// <summary>
108→  /// Saves data to storage. Updates cache and writes to disk.
109→  /// </summary>
110→  public override async Task Save(StorageKey key, byte[] data)
111→  {
112→    ThrowIfDisposed();
113→
114→    if(data == null)
115→      throw new ArgumentNullException(nameof(data));
116→
117→    var cacheKey = GetCacheKey(key);
118→    var filePath = GetFilePath(key);
119→
120→    await _lock.WaitAsync();
121→    try
122→    {
123→      // Create directory structure
124→      var directory = Path.GetDirectoryName(filePath);
125→      if(!string.IsNullOrEmpty(directory))
126→      {
127→        Directory.CreateDirectory(directory);
128→      }
129→
130→      // Write to disk
131→      await File.WriteAllBytesAsync(filePath, data);
132→
133→      // Update cache
134→      var cacheOptions = new MemoryCacheEntryOptions()
135→        .SetSize(data.Length)
136→        .SetSlidingExpiration(_cacheSlidingExpiration);
137→
138→      _cache.Set(cacheKey, data, cacheOptions);
139→    }
140→    finally
141→    {
142→      _lock.Release();
143→    }
144→  }
145→
146→  /// <summary>
147→  /// Removes data for a storage key. Removes from cache and deletes file.
148→  /// </summary>
149→  public override async Task Remove(StorageKey key)
150→  {
151→    ThrowIfDisposed();
152→
153→    var cacheKey = GetCacheKey(key);
154→    var filePath = GetFilePath(key);
155→
156→    await _lock.WaitAsync();
157→    try
158→    {
159→      // Remove from cache
160→      _cache.Remove(cacheKey);
161→
162→      // Delete file (ignore if doesn't exist)
163→      if(File.Exists(filePath))
164→      {
165→        File.Delete(filePath);
166→      }
167→    }
168→    finally
169→    {
170→      _lock.Release();
171→    }
172→  }
173→
174→  /// <summary>
175→  /// Loads all chunks matching a key prefix. Combines cached and disk data.
176→  /// </summary>
177→  public override async Task<IReadOnlyList<Chunk>> LoadRange(StorageKey keyPrefix)
178→  {
179→    ThrowIfDisposed();
180→
181→    var dirPath = GetFilePath(keyPrefix);
182→    var results = new Dictionary<string, Chunk>(); // Use dict to deduplicate
183→
184→    await _lock.WaitAsync();
185→    try
186→    {
187→      // Walk directory tree to find all files
188→      var diskFiles = await WalkDirectory(dirPath);
189→
190→      // Load each file (will hit cache if available)
191→      foreach(var filePath in diskFiles)
192→      {
193→        // Convert file path back to StorageKey
194→        var relativePath = Path.GetRelativePath(_baseDirectory, filePath);
195→        var components = ParseFilePathToKey(relativePath);
196→        var storageKey = new StorageKey(components);
197→
198→        // Check if key matches prefix
199→        if(storageKey.StartsWith(keyPrefix))
200→        {
201→          // Load data (hits cache if present)
202→          var data = await Load(storageKey);
203→          if(data != null)
204→          {
205→            var keyString = storageKey.ToDebugString();
206→            results[keyString] = new Chunk(storageKey, data);
207→          }
208→        }
209→      }
210→
211→      return results.Values.ToList();
212→    }
213→    finally
214→    {
215→      _lock.Release();
216→    }
217→  }
218→
219→  /// <summary>
220→  /// Removes all keys matching a prefix. Deletes directory tree and clears from cache.
221→  /// </summary>
222→  public override async Task RemoveRange(StorageKey keyPrefix)
223→  {
224→    ThrowIfDisposed();
225→
226→    var dirPath = GetFilePath(keyPrefix);
227→
228→    await _lock.WaitAsync();
229→    try
230→    {
231→      // Note: MemoryCache doesn't expose keys for enumeration
232→      // Cache entries will expire naturally via sliding expiration
233→
234→      // Delete directory tree from disk
235→      if(Directory.Exists(dirPath))
236→      {
237→        Directory.Delete(dirPath, recursive: true);
238→      }
239→    }
240→    catch(DirectoryNotFoundException)
241→    {
242→      // Directory already deleted, ignore
243→    }
244→    finally
245→    {
246→      _lock.Release();
247→    }
248→  }
249→
250→  /// <summary>
251→  /// Gets metadata about all chunks matching a key prefix without loading the full data.
252→  /// This is more efficient than the base implementation as it only reads file metadata.
253→  /// </summary>
254→  public override async Task<IReadOnlyList<ChunkInfo>> GetChunkInfo(StorageKey keyPrefix)
255→  {
256→    ThrowIfDisposed();
257→
258→    var dirPath = GetFilePath(keyPrefix);
259→    var results = new List<ChunkInfo>();
260→
261→    await _lock.WaitAsync();
262→    try
263→    {
264→      // Walk directory tree to find all files
265→      var diskFiles = await WalkDirectory(dirPath);
266→
267→      // Get metadata for each file
268→      foreach(var filePath in diskFiles)
269→      {
270→        // Convert file path back to StorageKey
271→        var relativePath = Path.GetRelativePath(_baseDirectory, filePath);
272→        var components = ParseFilePathToKey(relativePath);
273→        var storageKey = new StorageKey(components);
274→
275→        // Check if key matches prefix
276→        if(storageKey.StartsWith(keyPrefix))
277→        {
278→          // Get file size without loading data
279→          var fileInfo = new FileInfo(filePath);
280→          if(fileInfo.Exists)
281→          {
282→            results.Add(new ChunkInfo(storageKey, (int)fileInfo.Length));
283→          }
284→        }
285→      }
286→
287→      return results;
288→    }
289→    finally
290→    {
291→      _lock.Release();
292→    }
293→  }
294→
295→
296→  /// <summary>
297→  /// Converts a storage key to a file system path using directory sharding.
298→  /// </summary>
299→  /// <remarks>
300→  /// The first key component is split into two parts for sharding:
301→  /// - First 2 characters become a directory (prevents too many files in one dir)
302→  /// - Remaining characters become a subdirectory
303→  /// - Other components are appended as subdirectories
304→  ///
305→  /// Example: ["abc123def", "snapshot", "hash456"]
306→  /// → baseDir/ab/c123def/snapshot/hash456
307→  /// </remarks>
308→  string GetFilePath(StorageKey key)
309→  {
310→    if(key.Components.Count == 0)
311→      throw new ArgumentException("StorageKey must have at least one component");
312→
313→    var firstKey = key.Components[0];
314→    if(firstKey.Length < 2)
315→      throw new ArgumentException($"First key component must be at least 2 chars: {firstKey}");
316→
317→    // Shard: first 2 chars / remaining chars / other components
318→    var shardDir = firstKey[..2];         // First 2 chars
319→    var remaining = firstKey[2..];         // Rest of first key
320→
321→    var pathComponents = new List<string> { _baseDirectory, shardDir, remaining };
322→    pathComponents.AddRange(key.Components.Skip(1));
323→
324→    return Path.Combine(pathComponents.ToArray());
325→  }
326→
327→
328→  /// <summary>
329→  /// Gets the cache key for a storage key (uses ToDebugString for consistency).
330→  /// </summary>
331→  string GetCacheKey(StorageKey key) => key.ToDebugString();
332→
333→
334→  /// <summary>
335→  /// Converts a relative file path back to storage key components.
336→  /// Reverses the sharding: ab/c123/snapshot/hash → ["abc123", "snapshot", "hash"]
337→  /// </summary>
338→  List<string> ParseFilePathToKey(string relativePath)
339→  {
340→    var parts = relativePath.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
341→
342→    if(parts.Length < 2)
343→      throw new ArgumentException($"Invalid file path format: {relativePath}");
344→
345→    // Reconstruct first key: parts[0] + parts[1] (un-shard)
346→    var firstKey = parts[0] + parts[1];
347→
348→    var components = new List<string> { firstKey };
349→    components.AddRange(parts.Skip(2));
350→
351→    return components;
352→  }
353→
354→
355→  /// <summary>
356→  /// Recursively walks a directory and returns all file paths.
357→  /// Returns empty list if directory doesn't exist.
358→  /// </summary>
359→  async Task<List<string>> WalkDirectory(string dirPath)
360→  {
361→    var files = new List<string>();
362→
363→    if(!Directory.Exists(dirPath))
364→      return files;
365→
366→    try
367→    {
368→      // Get all files in current directory
369→      var directFiles = Directory.GetFiles(dirPath);
370→      files.AddRange(directFiles);
371→
372→      // Recursively process subdirectories
373→      var subdirectories = Directory.GetDirectories(dirPath);
374→      foreach(var subdir in subdirectories)
375→      {
376→        var subFiles = await WalkDirectory(subdir);
377→        files.AddRange(subFiles);
378→      }
379→    }
380→    catch(UnauthorizedAccessException)
381→    {
382→      // Skip directories we can't access
383→    }
384→    catch(DirectoryNotFoundException)
385→    {
386→      // Directory was deleted during traversal
387→    }
388→
389→    return files;
390→  }
391→
392→
393→  /// <summary>
394→  /// Disposes the adapter and releases resources.
395→  /// </summary>
396→  public void Dispose()
397→  {
398→    if(_disposed)
399→      return;
400→
401→    _disposed = true;
402→
403→    _cache.Dispose();
404→    _lock.Dispose();
405→  }
406→
407→
408→  /// <summary>
409→  /// Throws if the adapter has been disposed.
410→  /// </summary>
411→  void ThrowIfDisposed()
412→  {
413→    if(_disposed)
414→      throw new ObjectDisposedException(nameof(FileSystemStorageAdapter));
415→  }
416→}
417→
