420→/// Configuration options for FileSystemStorageAdapter.
421→/// </summary>
422→[PublicAPI]
423→public sealed class FileSystemStorageOptions
424→{
425→  /// <summary>
426→  /// Maximum cache size in bytes. Default: 100 MB.
427→  /// </summary>
428→  public long CacheSizeLimit { get; init; } = 100 * 1024 * 1024;
429→
430→  /// <summary>
431→  /// Sliding expiration time for cached entries. Default: 5 minutes.
432→  /// </summary>
433→  public TimeSpan CacheSlidingExpiration { get; init; } = TimeSpan.FromMinutes(5);
434→}
