  7→namespace Ray.Automerge.Repository;
  8→
  9→/// <summary>
 10→/// Central repository for managing Automerge documents with persistence and sync.
 11→/// </summary>
 12→/// <remarks>
 13→/// <para>
 14→/// The Repo is the main entry point of this library. To construct a Repo you will need
 15→/// an IStorageAdapter and one or more INetworkAdapters. Once you have a Repo you can
 16→/// use it to obtain DocHandles.
 17→/// </para>
 18→/// <para>
 19→/// This is a C# port of the TypeScript automerge-repo Repo class, maintaining API compatibility.
 20→/// </para>
 21→/// </remarks>
 22→[PublicAPI]
 23→public sealed class Repo : IDisposable
 24→{
 25→  // Subsystems
 26→  readonly StorageSubsystem? _storage;
 27→  readonly NetworkSubsystem _network;
 28→  readonly CollectionSynchronizer _synchronizer;
 29→
 30→  // Configuration
 31→  readonly PeerId _peerId;
 32→  readonly bool _isEphemeral;
 33→  readonly int _saveDebounceRate;
 34→  readonly ShareConfig _shareConfig;
 35→  readonly Func<IReadOnlyList<string>, Task<byte[]>>? _idFactory;
 36→
 37→  // Handle management
 38→  readonly Dictionary<string, IDocHandle> _handleCache = [];
 39→  readonly Dictionary<string, Task<IDocHandle>> _findInProgress = [];
 40→  readonly SemaphoreSlim _handleLock = new(1, 1);
 41→
 42→  // Save throttling
 43→  readonly Dictionary<string, CancellationTokenSource> _pendingSaves = [];
 44→  readonly SemaphoreSlim _saveLock = new(1, 1);
 45→
 46→  bool _isDisposed;
 47→
 48→
 49→  #region Events
 50→
 51→  /// <summary>
 52→  /// Raised when a document is loaded and ready.
 53→  /// </summary>
 54→  public event EventHandler<DocumentEventArgs>? DocumentLoaded;
 55→
 56→  /// <summary>
 57→  /// Raised when a document is deleted.
 58→  /// </summary>
 59→  public event EventHandler<DocumentDeletedEventArgs>? DocumentDeleted;
 60→
 61→  /// <summary>
 62→  /// Raised when a document is unavailable from all peers.
 63→  /// </summary>
 64→  public event EventHandler<DocumentUnavailableEventArgs>? DocumentUnavailable;
 65→
 66→  /// <summary>
 67→  /// Raised when a peer connects.
 68→  /// </summary>
 69→  public event EventHandler<PeerEventArgs>? PeerConnected;
 70→
 71→  /// <summary>
 72→  /// Raised when a peer disconnects.
 73→  /// </summary>
 74→  public event EventHandler<PeerEventArgs>? PeerDisconnected;
 75→
 76→  #endregion
 77→
 78→  #region Properties
 79→
 80→  /// <summary>
 81→  /// Gets the peer ID of this repository.
 82→  /// </summary>
 83→  public PeerId PeerId => _peerId;
 84→
 85→  /// <summary>
 86→  /// Gets the list of currently connected peers.
 87→  /// </summary>
 88→  public IReadOnlyList<PeerId> Peers => _network.Peers;
 89→
 90→  /// <summary>
 91→  /// Gets a read-only snapshot of all cached handles.
 92→  /// </summary>
 93→  public IReadOnlyDictionary<string, IDocHandle> Handles
 94→  {
 95→    get
 96→    {
 97→      _handleLock.Wait();
 98→      try
 99→      {
100→        return new ReadOnlyDictionary<string, IDocHandle>(
101→          new Dictionary<string, IDocHandle>(_handleCache));
102→      }
103→      finally
104→      {
105→        _handleLock.Release();
106→      }
107→    }
108→  }
109→
110→  #endregion
111→
112→
113→  /// <summary>
114→  /// Initializes a new repository with the specified configuration.
115→  /// </summary>
116→  /// <param name="config">Configuration for the repository.</param>
117→  /// <exception cref="ArgumentNullException">Thrown if config is null.</exception>
118→  public Repo(RepoConfig config)
119→  {
120→    if(config is null)
121→      throw new ArgumentNullException(nameof(config));
122→
123→    // Initialize identity
124→    _peerId = config.PeerId ?? PeerId.Generate();
125→    _isEphemeral = config.IsEphemeral;
126→    _saveDebounceRate = config.SaveDebounceRate;
127→    _shareConfig = config.ShareConfig ?? ShareConfig.AllowAll;
128→    _idFactory = config.IdFactory;
129→
130→    // Initialize storage subsystem
131→    if(config.Storage is not null)
132→    {
133→      _storage = new StorageSubsystem(config.Storage);
134→      _storage.DocumentLoaded += OnStorageDocumentLoaded;
135→      _storage.DocumentSaved += OnStorageDocumentSaved;
136→    }
137→
138→    // Initialize network subsystem
139→    _network = new NetworkSubsystem(config.NetworkAdapters);
140→    _network.PeerCandidate += OnNetworkPeerCandidate;
141→    _network.PeerDisconnected += OnNetworkPeerDisconnected;
142→    _network.MessageReceived += OnNetworkMessageReceived;
143→
144→    // Initialize synchronizer
145→    _synchronizer = new CollectionSynchronizer(
146→      GetDocument,
147→      UpdateDocument,
148→      GetPeerMetadata,
149→      RequestDocument,
150→      config.Denylist);
151→
152→    _synchronizer.MessageToSend += OnSynchronizerMessage;
153→    _synchronizer.SyncStateChanged += OnSynchronizerSyncStateChanged;
154→    _synchronizer.DocumentUnavailable += OnSynchronizerDocumentUnavailable;
155→
156→    // Set share and access policies
157→    if(_shareConfig.Announce is not null)
158→    {
159→      _synchronizer.SetSharePolicy(AdaptAnnouncePolicy);
160→    }
161→
162→    if(_shareConfig.Access is not null)
163→    {
164→      _synchronizer.SetAccessPolicy(AdaptAccessPolicy);
165→    }
166→  }
167→  
168→  
169→  /// <summary>
170→  /// Disposes the repository and releases all resources.
171→  /// </summary>
172→  public void Dispose()
173→  {
174→    if(_isDisposed) return;
175→
176→    _isDisposed = true;
177→
178→    // Cancel all pending saves
179→    _saveLock.Wait();
180→    try
181→    {
182→      foreach(var cts in _pendingSaves.Values)
183→      {
184→        cts.Cancel();
185→        cts.Dispose();
186→      }
187→
188→      _pendingSaves.Clear();
189→    }
190→    finally
191→    {
192→      _saveLock.Release();
193→    }
194→
195→    // Dispose synchronizer
196→    _synchronizer.Dispose();
197→
198→    // Dispose network subsystem
199→    _network.Dispose();
200→

  1→namespace Ray.Automerge.Repository.Network;
  2→
  3→/// <summary>
  4→/// Manages network communication across multiple adapters with message routing and deduplication.
  5→/// </summary>
  6→/// <remarks>
  7→/// <para>NetworkSubsystem provides:</para>
  8→/// <list type="bullet">
  9→/// <item><description>Support for multiple concurrent network adapters</description></item>
 10→/// <item><description>Message routing between adapters and the repo</description></item>
 11→/// <item><description>Ephemeral message deduplication to prevent gossip loops</description></item>
 12→/// <item><description>Peer connection lifecycle management</description></item>
 13→/// <item><description>Peer metadata storage</description></item>
 14→/// </list>
 15→/// <para>Thread Safety: This class is thread-safe. All public methods and properties can be called from any thread.</para>
 16→/// </remarks>
 17→[PublicAPI]
 18→public sealed class NetworkSubsystem : IDisposable
 19→{
 20→  readonly List<INetworkAdapter> _adapters = [];
 21→  readonly Dictionary<PeerId, INetworkAdapter> _peerToAdapter = [];
 22→  readonly Dictionary<string, PeerMetadata> _peerMetadata = [];
 23→  readonly HashSet<string> _seenEphemeralMessages = [];
 24→  readonly SemaphoreSlim _lock = new(1, 1);
 25→  bool _isDisposed;
 26→
 27→
 28→  /// <summary>
 29→  /// Raised when a new peer candidate is discovered by any adapter.
 30→  /// </summary>
 31→  public event EventHandler<PeerCandidateEventArgs>? PeerCandidate;
 32→
 33→  /// <summary>
 34→  /// Raised when a peer disconnects from any adapter.
 35→  /// </summary>
 36→  public event EventHandler<PeerDisconnectedEventArgs>? PeerDisconnected;
 37→
 38→  /// <summary>
 39→  /// Raised when a message is received from any adapter.
 40→  /// </summary>
 41→  public event EventHandler<MessageReceivedEventArgs>? MessageReceived;
 42→
 43→  /// <summary>
 44→  /// Returns true if at least one adapter is ready.
 45→  /// </summary>
 46→  public bool IsReady
 47→  {
 48→    get
 49→    {
 50→      ThrowIfDisposed();
 51→      _lock.Wait();
 52→      try
 53→      {
 54→        return _adapters.Any(a => a.IsReady);
 55→      }
 56→      finally
 57→      {
 58→        _lock.Release();
 59→      }
 60→    }
 61→  }
 62→
 63→  /// <summary>
 64→  /// Returns all currently connected peers.
 65→  /// </summary>
 66→  public IReadOnlyList<PeerId> Peers
 67→  {
 68→    get
 69→    {
 70→      ThrowIfDisposed();
 71→      _lock.Wait();
 72→      try
 73→      {
 74→        return _peerToAdapter.Keys.ToList();
 75→      }
 76→      finally
 77→      {
 78→        _lock.Release();
 79→      }
 80→    }
 81→  }
 82→
 83→
 84→  /// <summary>
 85→  /// Initializes a new instance of the NetworkSubsystem.
 86→  /// </summary>
 87→  /// <param name="adapters">Optional initial set of network adapters.</param>
 88→  public NetworkSubsystem(IEnumerable<INetworkAdapter>? adapters = null)
 89→  {
 90→    if(adapters is not null)
 91→    {
 92→      foreach(var adapter in adapters)
 93→      {
 94→        AddAdapter(adapter);
 95→      }
 96→    }
 97→  }
 98→
 99→  /// <summary>
100→  /// Disposes the NetworkSubsystem, disconnecting all adapters and releasing resources.
101→  /// </summary>
102→  public void Dispose()
103→  {
104→    if(_isDisposed) return;
105→
106→    _lock.Wait();
107→    try
108→    {
109→      _isDisposed = true;
110→
111→      // Disconnect and unwire all adapters
112→      foreach(var adapter in _adapters.ToList())
113→      {
114→        adapter.PeerCandidate -= OnAdapterPeerCandidate;
115→        adapter.PeerDisconnected -= OnAdapterPeerDisconnected;
116→        adapter.MessageReceived -= OnAdapterMessageReceived;
117→
118→        // Note: We don't call Disconnect() here as that's the responsibility of the adapter owner
119→      }
120→
121→      _adapters.Clear();
122→      _peerToAdapter.Clear();
123→      _peerMetadata.Clear();
124→      _seenEphemeralMessages.Clear();
125→    }
126→    finally
127→    {
128→      _lock.Release();
129→      _lock.Dispose();
130→    }
131→  }
132→
133→  
134→  // PUBLIC METHODS
135→  // ---------------------------------------------------------------------------------------------------------
136→
137→  /// <summary>
138→  /// Adds a network adapter to the subsystem.
139→  /// </summary>
140→  /// <param name="adapter">The adapter to add.</param>
141→  /// <exception cref="ArgumentNullException">Thrown if adapter is null.</exception>
142→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
143→  public void AddAdapter(INetworkAdapter adapter)
144→  {
145→    if(adapter is null) throw new ArgumentNullException(nameof(adapter));
146→    ThrowIfDisposed();
147→
148→    _lock.Wait();
149→    try
150→    {
151→      if(_adapters.Contains(adapter)) return;
152→
153→      _adapters.Add(adapter);
154→
155→      // Wire up events
156→      adapter.PeerCandidate += OnAdapterPeerCandidate;
157→      adapter.PeerDisconnected += OnAdapterPeerDisconnected;
158→      adapter.MessageReceived += OnAdapterMessageReceived;
159→    }
160→    finally
161→    {
162→      _lock.Release();
163→    }
164→  }
165→
166→  /// <summary>
167→  /// Removes a network adapter from the subsystem.
168→  /// </summary>
169→  /// <param name="adapter">The adapter to remove.</param>
170→  /// <exception cref="ArgumentNullException">Thrown if adapter is null.</exception>
171→  /// <exception cref="ObjectDisposedException">Thrown if the subsystem has been disposed.</exception>
172→  public void RemoveAdapter(INetworkAdapter adapter)
173→  {
174→    if(adapter is null) throw new ArgumentNullException(nameof(adapter));
175→    ThrowIfDisposed();
176→
177→    _lock.Wait();
178→    try
179→    {
180→      if(!_adapters.Remove(adapter)) return;
181→
182→      // Unwire events
183→      adapter.PeerCandidate -= OnAdapterPeerCandidate;
184→      adapter.PeerDisconnected -= OnAdapterPeerDisconnected;
185→      adapter.MessageReceived -= OnAdapterMessageReceived;
186→
187→      // Remove peers associated with this adapter
188→      var peersToRemove = _peerToAdapter
189→        .Where(kvp => kvp.Value == adapter)
190→        .Select(kvp => kvp.Key)
191→        .ToList();
192→
193→      foreach(var peer in peersToRemove)
194→      {
195→        _peerToAdapter.Remove(peer);
196→        _peerMetadata.Remove(peer);
197→      }
198→    }
199→    finally
200→    {

150→  }
151→
152→  /// <summary>
153→  /// Removes a shape from a layer by layer index and shape index.
154→  /// </summary>
155→  public void RemoveShape(ulong layerIndex, ulong shapeIndex)
156→  {
157→    ThrowIfDisposed();
158→    var layerId = _document.ListGetObject(_layersListId, layerIndex)
159→      ?? throw new InvalidOperationException($"No layer at index {layerIndex}.");
160→    var shapesListId = _document.GetObject(layerId, "shapes")
161→      ?? throw new InvalidOperationException("Layer has no shapes list.");
162→
163→    _document.ListRemove(shapesListId, shapeIndex);
164→    _document.Commit($"Remove shape at layer {layerIndex}, index {shapeIndex}");
165→  }
166→
167→  /// <summary>
168→  /// Adds a new layer at the end of the layers list.
169→  /// </summary>
170→  public Layer AddLayer(string name)
171→  {
172→    ThrowIfDisposed();
173→    ulong index = _document.ListLength(_layersListId);
174→    var layerId = _document.ListInsertObject(_layersListId, index, AutomergeContainerType.Map);
175→    _document.PutString(layerId, "name", name);
176→    _document.PutBoolean(layerId, "visible", true);
177→    var shapesListId = _document.PutObject(layerId, "shapes", AutomergeContainerType.List);
178→    _document.Commit($"Add layer: {name}");
179→
180→    return new Layer
181→    {
182→      ObjectId = layerId,
183→      ShapesListId = shapesListId,
184→      Name = name,
185→      IsVisible = true,
186→    };
187→  }
188→
189→  /// <summary>
190→  /// Removes a layer by its index.
191→  /// </summary>
192→  public void RemoveLayer(ulong index)
193→  {
194→    ThrowIfDisposed();
195→    _document.ListRemove(_layersListId, index);
196→    _document.Commit($"Remove layer at {index}");
197→  }
198→
199→  /// <summary>
200→  /// Toggles a layer's visibility.
201→  /// </summary>
202→  public void ToggleLayerVisibility(AutomergeObjectId layerId, bool isVisible)
203→  {
204→    ThrowIfDisposed();
205→    _document.PutBoolean(layerId, "visible", isVisible);
206→    _document.Commit($"Set layer visibility: {isVisible}");
207→  }
208→
209→  /// <summary>
210→  /// Reads the full canvas state from the document.
211→  /// </summary>
212→  public List<Layer> ReadCanvas()
213→  {
214→    ThrowIfDisposed();
215→    var layers = new List<Layer>();
216→    ulong layerCount = _document.ListLength(_layersListId);
217→
218→    for(ulong i = 0; i < layerCount; i++)
219→    {
220→      var layerId = _document.ListGetObject(_layersListId, i);
221→      if(layerId is null)
222→      {
223→        continue;
224→      }
225→
226→      var shapesListId = _document.GetObject(layerId, "shapes");
227→      if(shapesListId is null)
228→      {
229→        continue;
230→      }
231→
232→      var layer = new Layer
233→      {
234→        ObjectId = layerId,
235→        ShapesListId = shapesListId,
236→        Name = _document.GetString(layerId, "name") ?? string.Empty,
237→        IsVisible = _document.GetBoolean(layerId, "visible") ?? true,
238→      };
239→
240→      ulong shapeCount = _document.ListLength(shapesListId);
241→      for(ulong j = 0; j < shapeCount; j++)
242→      {
243→        var shapeId = _document.ListGetObject(shapesListId, j);
244→        if(shapeId is null)
245→        {
246→          continue;
247→        }
248→
249→        string typeStr = _document.GetString(shapeId, "type") ?? "Rectangle";
250→        var shapeType = Enum.TryParse<ShapeType>(typeStr, out var parsed) ? parsed : ShapeType.Rectangle;
251→
252→        layer.Shapes.Add(new CanvasObject
253→        {
254→          ObjectId = shapeId,
255→          Name = _document.GetString(shapeId, "name") ?? string.Empty,
256→          Type = shapeType,
257→          X = _document.GetDouble(shapeId, "x") ?? 0,
258→          Y = _document.GetDouble(shapeId, "y") ?? 0,
259→          Width = _document.GetDouble(shapeId, "width") ?? 0,
260→          Height = _document.GetDouble(shapeId, "height") ?? 0,
261→          Color = _document.GetString(shapeId, "color") ?? "#000000",
