292→  void OnShapesCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e)
293→  {
294→    if(_canvas is null || _viewModel is null)
295→    {
296→      return;
297→    }
298→
299→    switch(e.Action)
300→    {
301→      case NotifyCollectionChangedAction.Add:
302→        if(e.NewItems is not null)
303→        {
304→          foreach(ShapeViewModel shape in e.NewItems)
305→          {
306→            AddShapeToCanvas(shape);
307→          }
308→        }
309→
310→        break;
311→
312→      case NotifyCollectionChangedAction.Remove:
313→        if(e.OldItems is not null)
314→        {
315→          foreach(ShapeViewModel shape in e.OldItems)
316→          {
317→            RemoveShapeFromCanvas(shape);
318→          }
319→        }
320→
321→        break;
322→
323→      case NotifyCollectionChangedAction.Reset:
324→        ClearAllShapes();
325→        RenderAllShapes();
326→        break;
327→    }
328→  }
329→
330→  void RenderAllShapes()
331→  {
332→    if(_viewModel is null)
333→    {
334→      return;
335→    }
336→
337→    foreach(var shape in _viewModel.Shapes)
338→    {
339→      AddShapeToCanvas(shape);
340→    }
341→  }
342→
343→  void AddShapeToCanvas(ShapeViewModel shape)
344→  {
345→    if(_canvas is null)
346→    {
347→      return;
348→    }
349→
350→    Control shapeControl = CreateShapeControl(shape);
351→    Canvas.SetLeft(shapeControl, shape.X);
352→    Canvas.SetTop(shapeControl, shape.Y);
353→    _canvas.Children.Add(shapeControl);
354→    _shapeControls[shape] = shapeControl;
355→
356→    // Listen for property changes to update rendering
357→    shape.PropertyChanged += (_, args) =>
358→    {
359→      if(args.PropertyName is "X" or "Y")
360→      {
361→        Canvas.SetLeft(shapeControl, shape.X);
362→        Canvas.SetTop(shapeControl, shape.Y);
363→      }
364→      else if(args.PropertyName is "Width" or "Height")
365→      {
366→        shapeControl.Width = shape.Width;
367→        shapeControl.Height = shape.Height;
368→      }
369→      else if(args.PropertyName == "Color")
370→      {
371→        UpdateShapeColor(shapeControl, shape);
372→      }
373→    };
374→  }
375→
376→  Control CreateShapeControl(ShapeViewModel shape)
377→  {
378→    var brush = new SolidColorBrush(Color.Parse(shape.Color));
379→
380→    Control inner;
381→    if(shape.Type == ShapeType.Ellipse)
382→    {
383→      inner = new Ellipse
384→      {
385→        Width = shape.Width,
386→        Height = shape.Height,
387→        Fill = brush,
388→        Stroke = Brushes.Transparent,
389→        StrokeThickness = 2,
390→      };
391→    }
392→    else
393→    {
394→      inner = new Rectangle
395→      {
396→        Width = shape.Width,
397→        Height = shape.Height,
398→        Fill = brush,
399→        Stroke = Brushes.Transparent,
400→        StrokeThickness = 2,
401→        RadiusX = 2,
402→        RadiusY = 2,
403→      };
404→    }
405→
406→    var wrapper = new Border
407→    {
408→      Child = inner,
409→      Tag = shape,
410→      Cursor = new Cursor(StandardCursorType.Hand),
411→    };
412→
413→    wrapper.PointerPressed += OnShapePointerPressed;
414→
415→    return wrapper;
416→  }
417→
418→  void UpdateShapeColor(Control control, ShapeViewModel shape)
419→  {
420→    if(control is Border { Child: Shape avShape })
421→    {
422→      avShape.Fill = new SolidColorBrush(Color.Parse(shape.Color));
423→    }
424→  }
425→
426→  void RemoveShapeFromCanvas(ShapeViewModel shape)
427→  {
428→    if(_canvas is null || !_shapeControls.TryGetValue(shape, out var control))
429→    {
430→      return;
431→    }
432→
433→    _canvas.Children.Remove(control);
434→    _shapeControls.Remove(shape);
435→  }
436→
437→  void ClearAllShapes()
438→  {
439→    if(_canvas is null)
440→    {
441→      return;
442→    }
443→
444→    foreach(var control in _shapeControls.Values)
445→    {
446→      _canvas.Children.Remove(control);
447→    }
448→
449→    _shapeControls.Clear();

