140→  /// <summary>
141→  /// Called when a new peer connects. Begins syncing all documents with this peer.
142→  /// </summary>
143→  public void OnPeerConnected(PeerId peerId)
144→  {
145→    ThrowIfDisposed();
146→
147→    // Collect deferred operations
148→    var docsToSync = new List<(string documentId, DocSynchronizer docSync)>();
149→
150→    _lock.Wait();

200→
201→    // Dispose storage subsystem
202→    _storage?.Dispose();
203→
204→    // Dispose all handles
205→
206→    _handleLock.Wait();
207→    try
208→    {
209→      foreach(var handle in _handleCache.Values)
210→      {
211→        handle.Dispose();
212→      }
213→
214→      _handleCache.Clear();
215→    }
216→    finally
217→    {
218→      _handleLock.Release();
219→    }
220→
221→    // Dispose locks
222→    _handleLock.Dispose();
223→    _saveLock.Dispose();
224→  }
