### **10. AutomergeService Pattern**

Each app defines its own `AutomergeService` wrapping `AutomergeDocument`:

```csharp
sealed class AutomergeService : IDisposable {
    readonly AutomergeDocument _document;
    readonly bool _ownsDocument;  // Dispose document on cleanup?

    // Constructor: Create standalone
    public AutomergeService() {
        _document = AutomergeDocument.Create();
        // ... initialize schema
        _ownsDocument = true;
    }

    // Static Factory: Wrap existing document (from Repo)
    public static AutomergeService FromDocument(AutomergeDocument document) {
        var keys = document.GetKeys(document.RootId).ToList();
        if (!keys.Contains("expectedKey")) {
            // Initialize schema if missing
            document.PutObject(document.RootId, "expectedKey", ...);
        }
        return new AutomergeService(document, ownsDocument: false);
    }

    // CRUD methods (domain-specific)
    public void AddShape(...) { ... }
    public List<Layer> ReadCanvas() { ... }
    public byte[] Save() => _document.Save();
}
```

