486→  void OnCanvasPointerPressed(object? sender, PointerPressedEventArgs e)
487→  {
488→    if(_canvas is null || _viewModel is null)
489→    {
490→      return;
491→    }
492→
493→    var point = e.GetPosition(_canvas);
494→
495→    // Deselect current shape if clicking on empty canvas
496→    _viewModel.SelectedShape = null;
497→    UpdateSelectionVisual();
498→
499→    // Start drawing a new shape
500→    _isDrawing = true;
501→    _drawStart = point;
502→
503→    _drawPreview = new Border
504→    {
505→      BorderBrush = new SolidColorBrush(Color.Parse("#999")),
506→      BorderThickness = new Thickness(1),
507→      Background = new SolidColorBrush(Color.Parse(_viewModel.SelectedColor), 0.3),
508→    };
509→
510→    Canvas.SetLeft(_drawPreview, point.X);
511→    Canvas.SetTop(_drawPreview, point.Y);
512→    _canvas.Children.Add(_drawPreview);
513→
514→    e.Handled = true;
